UPDATE pull_task_creator_deletion SET status=6, reason_code='CREATOR_RESERVATION_RELEASED',
  reason_message='执行已结束且未提交注销，建群账号预留已释放',updated_at=#{now}
WHERE id=#{row.id} AND tenant_id=#{row.tenantId} AND task_id=#{row.taskId}
  AND group_execution_id=#{row.groupExecutionId} AND status=0 AND submitted_at IS NULL

UPDATE pull_task_creator_deletion
SET status = 1, manager_account_id = #{row.managerAccountId}, group_jid = #{row.groupJid},
    creation_before = #{row.creationBefore}, evidence_json = #{row.evidenceJson},
    observed_at = #{row.observedAt}, submitted_at = #{row.submittedAt},
    deadline_at = #{row.deadlineAt}, updated_at = #{row.updatedAt}
WHERE id = #{row.id} AND status = 0 AND operation_id = #{row.operationId}
  AND creator_account_id = #{row.creatorAccountId}
  AND creator_identity_hash = #{row.creatorIdentityHash}
  AND create_operation_id = #{row.createOperationId}
